import { useState, useRef } from 'react';

function AddVehicle({ user, onAdded }) {
  const [form, setForm] = useState({
    brand: '',
    model: '',
    segment: 'Economy',
    pricePerDay: '',
    campus: '',
  });
  const [imageFile, setImageFile] = useState(null);
  const [preview, setPreview] = useState(null);
  const [loading, setLoading] = useState(false);
  const [success, setSuccess] = useState('');
  const [error, setError] = useState('');
  const fileInputRef = useRef();

  const handleFileChange = (e) => {
    const file = e.target.files[0];
    if (!file) return;
    setImageFile(file);
    setPreview(URL.createObjectURL(file));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    setSuccess('');
    setError('');

    try {
      let imageUrl = '';

      // Önce görseli yükle
      if (imageFile) {
        const formData = new FormData();
        formData.append('image', imageFile);
        const uploadRes = await fetch('http://localhost:3002/api/upload', {
          method: 'POST',
          body: formData,
        });
        const uploadData = await uploadRes.json();
        if (!uploadRes.ok) throw new Error('Görsel yüklenemedi.');
        imageUrl = uploadData.url;
      }

      // Aracı kaydet
      const res = await fetch('http://localhost:3002/api/vehicles', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ ...form, ownerId: user.id, image: imageUrl }),
      });

      if (res.ok) {
        setSuccess('Araç başarıyla eklendi!');
        setForm({ brand: '', model: '', segment: 'Economy', pricePerDay: '', campus: '' });
        setImageFile(null);
        setPreview(null);
        if (fileInputRef.current) fileInputRef.current.value = '';
        onAdded();
        setTimeout(() => setSuccess(''), 3000);
      }
    } catch (err) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="add-vehicle">
      <h2>Araç Ekle</h2>
      <form onSubmit={handleSubmit} className="add-vehicle-form">
        <input
          placeholder="Marka (örn: Toyota)"
          value={form.brand}
          onChange={(e) => setForm({ ...form, brand: e.target.value })}
          required
        />
        <input
          placeholder="Model (örn: Corolla)"
          value={form.model}
          onChange={(e) => setForm({ ...form, model: e.target.value })}
          required
        />
        <select
          value={form.segment}
          onChange={(e) => setForm({ ...form, segment: e.target.value })}
        >
          <option value="Economy">Economy</option>
          <option value="Standard">Standard</option>
          <option value="Premium">Premium</option>
          <option value="SUV">SUV</option>
        </select>
        <input
          type="number"
          placeholder="Günlük fiyat (₺)"
          value={form.pricePerDay}
          onChange={(e) => setForm({ ...form, pricePerDay: e.target.value })}
          required
        />
        <input
          placeholder="Kampüs (örn: Yaşar Üniversitesi)"
          value={form.campus}
          onChange={(e) => setForm({ ...form, campus: e.target.value })}
          required
        />

        {/* Görsel yükleme */}
        <div className="upload-area" onClick={() => fileInputRef.current.click()}>
          {preview ? (
            <img src={preview} alt="Önizleme" className="upload-preview" />
          ) : (
            <div className="upload-placeholder">
              <span className="upload-icon">📷</span>
              <span>Araç fotoğrafı yükle</span>
              <small>JPG, PNG, JPEG (max 5MB)</small>
            </div>
          )}
          <input
            ref={fileInputRef}
            type="file"
            accept="image/*"
            onChange={handleFileChange}
            style={{ display: 'none' }}
          />
        </div>
        {preview && (
          <button
            type="button"
            className="remove-img-btn"
            onClick={() => { setPreview(null); setImageFile(null); fileInputRef.current.value = ''; }}
          >
            Görseli Kaldır
          </button>
        )}

        {error && <p className="error">{error}</p>}
        {success && <p className="success">{success}</p>}
        <button type="submit" disabled={loading}>
          {loading ? 'Ekleniyor...' : 'Araç Ekle'}
        </button>
      </form>
    </div>
  );
}

export default AddVehicle;
